INSERT INTO feature VALUES('effects-as-data','effects','Effects as data, replayed by the kernel','effect-rows','partial','notable',NULL,'A program over a row of operations is written as a tree, the free model of its operations, its row a sum of operation types and each handler a fold, so every declaration is pure and the kernel replays it whole: an operation outside a program''s row is refused by the checker and, forged past it, by the kernel at that program. A native deep handler crosses by this translation, its effect''s free model, one constructor per operation, admitted ahead of it and its clauses the fold, whether a capability scope writes them, names a model or leaves them to the one model in scope (`exit.gandr` and `state-handler.gandr`, written by hand in `tree-exit.gandr` and `tree-state.gandr`), so a resumption at another type than the reply is the kernel''s refusal. A declaration at a row of operations crosses the same way, as a program of its row''s free model, which the row and the level name alike in every session: a host operation is a constructor of the model, and a call at the row or at a smaller row folds its program into the rest (`probability/draws.gandr` and `reals/boundary.gandr`). A handler inside a row crosses as the same fold: a call in its subject folds into the subject''s program, and its clauses return programs of the outer row (`probability/seeded.gandr`, whose `lcg` passes each draw that it cannot answer to the model outside it). The forms past it cross after (#2742).','core-checker kernel-core','corpus/model/effects/tree.gandr corpus/model/effects/tree-state.gandr corpus/model/effects/tree-rows.gandr corpus/pathological/effects/tree-rows.gandr corpus/model/effects/exit.gandr corpus/model/effects/tree-exit.gandr corpus/model/effects/state-handler.gandr corpus/model/probability/draws.gandr corpus/model/reals/boundary.gandr corpus/model/probability/seeded.gandr crates/surface-corpus/src/kernel_export.rs','corpus/ledger/features/effects-as-data.gandr','#2742');
